What does this program print?

```swift
enum E: Error { case a, b(Int) }
func f(_ x: Int) throws -> Int {
    if x < 0 { throw E.a }
    if x > 9 { throw E.b(x) }
    return x * 2
}
var out: [String] = []
for x in [3, -1, 12] {
    do {
        out.append(String(try f(x)))
    } catch E.b(let n) {
        out.append("big \(n)")
    } catch {
        out.append("other")
    }
}
print(out.joined(separator: ", "))
```

What does this program print?

```swift
struct Bad: Error {}
func half(_ n: Int) throws -> Int {
    guard n % 2 == 0 else { throw Bad() }
    return n / 2
}
let results = [8, 5, 6, 7].map { try? half($0) }
print(results.compactMap { $0 }.reduce(0, +))
```

